ValidationRule.errorConditionFormula:
AND(
    ISCHANGED(Sub_Status__c),
    OR(
        /* Dispatch */
        AND(
            ISPICKVAL(Sub_Status__c, "Dispatch"),
            ISBLANK(TEXT(Dispatch_To_Branch__c))
        ),

        /* Collected by Customer */
        AND(
            ISPICKVAL(Sub_Status__c, "Collected by Customer"),
            ISBLANK(TEXT(Collected_From_Branch__c))
        ),

        /* Dispatch Return */
        AND(
            ISPICKVAL(Sub_Status__c, "Dispatch Return"),
            ISBLANK(Returned_From__c)
        )
    )
)
